def enabled(): return os.getenv("RECORD_FB_SCAN_20260829_EVENING","0").strip().lower() in {"1","true","yes","on"}

def _sheet(book,title,header):
    try:return book.worksheet(title)
    except Exception:
        ws=book.add_worksheet(title=title,rows=1000,cols=max(12,len(header))); ws.append_row(header,value_input_option="RAW"); return ws

def run():
    if not enabled(): return {"enabled":False}
    now=datetime.now(timezone.utc).isoformat(timespec="seconds")
