        onotes=json.dumps({"district":x["district"],"type":x["type"],"bedrooms":x["bedrooms"],"bathrooms":x["bathrooms"],"pool":x["pool"],"restrictions":x["restrictions"],"original_listing_text":x["original_text"],"ru_summary":x["original_text"],"original_message":None,"translation_ru":None,"free_periods":x["availability"],"occupied_periods":"not provided","seasonal_prices":x["minimum_stay"],"minimum_stay":x["minimum_stay"],"booking_terms":"advance amount, payment method, payment deadline, cancellation and booking point require owner confirmation","last_reply":None,"conversation_url":None,"contact_internal":x["contact"],"last_checked":now},ensure_ascii=False)
